def transform(grid):
    g = np.array(grid)
    out = g.copy()
    TARGET, WALL = 3, 5

    def norm(cells):
        best = None
        pts = [(y, x) for y, x in cells]
        for k in range(8):
            q = []
            for y, x in pts:
                if k & 4:
                    y, x = x, y
                if k & 1:
                    y = -y
                if k & 2:
                    x = -x
                q.append((y, x))
            my = min(p[0] for p in q); mx = min(p[1] for p in q)
            t = tuple(sorted((a - my, b - mx) for a, b in q))
            if best is None or t < best:
                best = t
        return best

    legend = {}
    sizes = {}
    for o in objects(g, bg=background(g)):
        if o["colour"] in (TARGET, WALL):
            continue
        legend[norm(o["cells"])] = o["colour"]
        sizes[o["size"]] = o["colour"]

    groups = {}
    for comp in components(g == TARGET):
        key = norm(comp)
        col = legend.get(key, sizes.get(len(comp)))
        if col is None:
            continue
        groups.setdefault(col, []).append(comp)

    for col, comps in groups.items():
        for comp in comps:
            for y, x in comp:
                out[y, x] = col
        emit(out, f"Recoloured {len(comps)} green shape(s) matching the legend shape of colour {col} to {col}.")

    emit(out, "All green shapes recoloured according to the legend.")
    return out
